USE visiray_dev;
START TRANSACTION;

-- 自动生成自：导入测试 .xlsx；仅新增缺少零件号的记录。
-- 已按当前启用的 VSR 12 位规则生成，版本号按 Excel 中的四位版本创建。

ON DUPLICATE KEY UPDATE part_name = VALUES(part_name);

-- Excel 中填写了版本号的零件，同时创建启用版本；没有版本号的零件保持无版本。
ON DUPLICATE KEY UPDATE status = VALUES(status);

-- 每个零件只有一个 Excel 版本时，将其设为当前版本。
UPDATE part_number p JOIN part_number_versions v ON v.part_id = p.part_id SET p.current_version_id = v.id, v.is_current = 1 WHERE p.part_id IN ('VSR101111200006','VSR101111200007','VSR202100100002','VSR202100100003','VSR202100100004','VSR202100100005','VSR202100100006','VSR202100100007','VSR202100100008','VSR202100100009','VSR202100100010','VSR101111200008','VSR101111200009','VSR101111200010','VSR101114100013','VSR101111200014','VSR101114100015');
UPDATE part_number_versions v JOIN part_number p ON p.part_id = v.part_id SET v.is_current = (p.current_version_id = v.id) WHERE p.part_id IN ('VSR101111200006','VSR101111200007','VSR202100100002','VSR202100100003','VSR202100100004','VSR202100100005','VSR202100100006','VSR202100100007','VSR202100100008','VSR202100100009','VSR202100100010','VSR101111200008','VSR101111200009','VSR101111200010','VSR101114100013','VSR101111200014','VSR101114100015');

COMMIT;
